create or replace function public.notify_broker_on_crm_request_reply() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.admin_response is distinct from old.admin_response and new.admin_response is not null and new.created_by is not null then insert into public.crm_user_notifications(user_id,company_id,request_id,title,message,entity_type,action,status) values (new.created_by,new.company_id,null,'Resposta à sua solicitação','O administrador respondeu: '||left(new.admin_response,500),'crm_request_reply','view_request:'||new.id::text,'new'); end if; return new; end; $$; drop trigger if exists trg_notify_broker_crm_request_reply on public.crm_requests; create trigger trg_notify_broker_crm_request_reply after update of admin_response on public.crm_requests for each row execute function public.notify_broker_on_crm_request_reply();